<div class="page-header"><div><p class="eyebrow">COURSE CATALOGUE</p><h1>Academic courses</h1><p>Courses, credit units, departments, levels and status.</p></div><?php if(AuthMiddleware::user()['role_slug']==='administrator'):?><a class="btn btn-primary" href="/courses/new">+ Add course</a><?php endif; ?></div>
<section class="panel"><form method="get" action="/courses" class="search-row"><input type="search" class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search course code or title"><button class="btn btn-primary">Search</button></form><div class="table-scroll"><table class="table table-clean"><thead><tr><th>Code</th><th>Course title</th><th>Department</th><th>Level</th><th>Units</th><th>Semester</th><th>Status</th><?php if(AuthMiddleware::user()['role_slug']==='administrator'):?><th>Action</th><?php endif;?></tr></thead><tbody><?php foreach($items as $r):?><tr><td><strong><?= e($r['code']) ?></strong></td><td><?= e($r['title']) ?></td><td><?= e($r['department_name']) ?></td><td><?= e($r['level_name']) ?></td><td><?= (int)$r['credit_units'] ?></td><td><?= (int)$r['semester_number'] ?></td><td><span class="status-pill <?= e($r['status']) ?>"><?= e($r['status']) ?></span></td><?php if(AuthMiddleware::user()['role_slug']==='administrator'):?><td><div class="inline-actions"><a class="btn btn-outline-primary btn-sm" href="/courses/edit?id=<?= (int)$r['id'] ?>">Edit</a><form method="post" action="/courses/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= $r['status']==='active'?'inactive':'active' ?>"><button class="btn btn-outline-secondary btn-sm"><?= $r['status']==='active'?'Deactivate':'Activate' ?></button></form></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php if(!$items):?><p class="empty-state">No matching courses.</p><?php endif; ?><?= page_links($page,$total,'/courses?q='.rawurlencode($search)) ?></section>
